CREATE TABLE IF NOT EXISTS kika_user(id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,email_verified INTEGER NOT NULL,image TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,username TEXT UNIQUE,display_username TEXT);
CREATE TABLE IF NOT EXISTS kika_session(id TEXT PRIMARY KEY NOT NULL,expires_at INTEGER NOT NULL,token TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,ip_address TEXT,user_agent TEXT,user_id TEXT NOT NULL REFERENCES kika_user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS kika_account(id TEXT PRIMARY KEY NOT NULL,account_id TEXT NOT NULL,provider_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES kika_user(id) ON DELETE CASCADE,access_token TEXT,refresh_token TEXT,id_token TEXT,access_token_expires_at INTEGER,refresh_token_expires_at INTEGER,scope TEXT,password TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kika_verification(id TEXT PRIMARY KEY NOT NULL,identifier TEXT NOT NULL,value TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER,updated_at INTEGER);
CREATE TABLE IF NOT EXISTS kika_rate_limit(id TEXT PRIMARY KEY NOT NULL,key TEXT NOT NULL UNIQUE,count INTEGER NOT NULL,last_request INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kika_catalog(id TEXT PRIMARY KEY NOT NULL,document TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kika_media(id TEXT PRIMARY KEY NOT NULL,data BLOB NOT NULL,created_at TEXT NOT NULL);
